            var flags = { lateUS: false, veryLateUS: false, rushQuality: false, twoStories: false, rushMissed: false, distant: markets.indexOf('europe') >= 0 };
            var revenue = 0;
            var extraCost = 0;
            for (var i = 0; i < 2; i++) {
                var mk = this.MARKETS[markets[i]];
                var mode = this.MODES[g(i === 0 ? 'entryMode1' : 'entryMode2')];
                var months = mode.months + mk.extraMonths;
                extraCost += (upto >= 2) ? mk.extraCost : 0;
                var timing = months <= 6 ? 1 : (months <= 10 ? 0.9 : (months <= 14 ? 0.8 : 0.7));
                var share = 1;
                if (markets[i] === 'usa') {
                    timing = 1;
                    if (resp === 'accelerate') {
                        if (mode.months <= 6) { share = 1.0; flags.rushQuality = true; }
                        else { share = mode.months <= 10 ? 0.7 : 0.5; flags.rushMissed = true; }
                    } else if (resp === 'maintain') {
                        share = mode.months <= 9 ? 0.9 : (mode.months <= 12 ? 0.7 : 0.5);
                    } else {
                        share = mode.months <= 10 ? 0.65 : 0.5;
                    }
                    if (upto >= 3 && mode.months > 10) flags.veryLateUS = true;
                    if (upto >= 3 && mode.months > 9 && resp !== 'accelerate') flags.lateUS = true;
                    if (upto < 3) share = 0.9;
                }
                var p = price;
                if (i === 1) {
                    var localTop = mk.high;
                    if (level >= 3) p = localTop;
                    else if (level === 2) p = (price + localTop) / 2;
                }
                var pf = this.priceFactor(mk, p);
                var story = 1;
                if (i === 0 && resp === 'differentiate' && price <= 20) { story = 0.85; flags.twoStories = true; }
                var quality = (revealed && flags.rushQuality && markets[i] === 'usa') ? 0.8 : 1;
                var w = i === 0 ? 1 : this.SECONDARY_WEIGHT;
                revenue += w * mk.potential * mk.access * mode.revMult * timing * share * pf * story * quality * this.locFactor(level) * mkt * K;
            }
            var margin = 0.24;
            if (resp === 'differentiate') margin = flags.twoStories ? 0.24 : 0.31;
            if (resp === 'accelerate' && revealed && flags.rushQuality) margin = 0.16;
            return { revenue: revenue * 1000000, contribution: revenue * margin * 1000000, margin: margin, extraCost: extraCost, flags: flags };
        },
        roundOf: function(k) {
            return { marketPriority: 1, researchBudget: 1, entryMode1: 2, entryMode2: 2, responseStrategy: 3, marketingBudget: 3, localizationLevel: 4, pricePoint: 4 }[k];
        },
        invested: function(dec, upto) {
            var markets = this.COMBOS[dec.marketPriority] || this.COMBOS.usa_mexico;
            var inv = dec.researchBudget || 0;
            if (upto >= 2) inv += this.MODES[dec.entryMode1].cost + this.MODES[dec.entryMode2].cost + this.MARKETS[markets[0]].extraCost + this.MARKETS[markets[1]].extraCost;
            if (upto >= 3) inv += dec.marketingBudget + (dec.responseStrategy === 'accelerate' ? 400000 : 0);
            if (upto >= 4) inv += dec.localizationLevel * 40000;
            return inv;
        },
        /* The board score: year-3 contribution and contribution per dollar invested, one function for every period. */
        score: function(contribution, invested) {
            if (invested <= 0) return 0;
            var c = Math.max(0, contribution / 1000000) / this.SCORE_REF_CONTRIB;
            var r = Math.max(0, (contribution / invested)) / this.SCORE_REF_RETURN;
            var v = Math.pow(Math.pow(c, 0.4) * Math.pow(r, 0.6), this.SCORE_GAMMA);
            return Math.max(0, Math.min(100, Math.round(v * 100)));
        },
        tier: function(s) { return s >= 80 ? 'excellent' : (s >= 60 ? 'good' : (s >= 40 ? 'satisfactory' : 'needs_improvement')); }
    };
    /* MODEL-END */

    class ExpansionAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'La Expansion';
            this.version = '1.2.0';

            this.ROUNDS = [
                { titleKey: 'round1_title', briefingKey: 'round1_briefing', controlsId: 'round1Controls' },
                { titleKey: 'round2_title', briefingKey: 'round2_briefing', controlsId: 'round2Controls' },
                { titleKey: 'round3_title', briefingKey: 'round3_briefing', controlsId: 'round3Controls' },
                { titleKey: 'round4_title', briefingKey: 'round4_briefing', controlsId: 'round4Controls' }
            ];

            this.ENTRY_MODES = EXP_MODEL.MODES;
            this.MARKET_COMBOS = EXP_MODEL.COMBOS;
            this._langBound = false;
        }

        _t(key) {
            return window.mySimulation ? window.mySimulation.t(key) : key;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: EXP_MODEL.CAPITAL,
                    totalInvested: 0,
                    projectedRevenueY3: 0,
                    projectedContribution: 0,
                    projectedMargin: 0,
                    strategicScore: 0,
                    plan: {},
                    flags: {},
                    marketPriority: '',
                    markets: [],
                    investmentHistory: [],
                    revenueHistory: [],
                    scoreHistory: [],
                    roundDescriptions: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    marketPriority: 'usa_mexico',
                    researchBudget: 100000,
                    entryMode1: 'distributor',
                    entryMode2: 'jv',
                    responseStrategy: 'maintain',
                    marketingBudget: 400000,
                    localizationLevel: 1,
                    pricePoint: 20
                };
            }
            this._updateBriefing(state);
            this._setupLocalizationSlider();
            this._bindLanguage();
        }

        _bindLanguage() {
            if (this._langBound) return;
            this._langBound = true;
            var self = this;
            var repaint = function() {
                setTimeout(function() {
                    if (window.mySimulation && window.mySimulation.state) self._updateBriefing(window.mySimulation.state);
                }, 0);
            };
            document.addEventListener('express:langchanged', repaint);
            try {
                if (window.mySimulation && window.mySimulation.eventBus) window.mySimulation.eventBus.on('language:changed', repaint);
            } catch (e) { /* no event bus */ }
        }

        _setupLocalizationSlider() {
            var slider = document.getElementById('localizationInput');
            var display = document.getElementById('localizationValue');
            if (slider && display) {
                display.textContent = slider.value;
                slider.addEventListener('input', function() {
                    display.textContent = slider.value;
                });
            }
        }

        _marketName(code) {
            return this._t('mk_' + code);
        }

        _updateBriefing(state) {
            var period = state.currentPeriod || 1;
            var finished = period > this.ROUNDS.length;
            var idx = Math.min(period - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var titleEl = document.getElementById('roundTitleDisplay');
            if (titleEl) titleEl.textContent = finished ? this._t('debrief_title') : this._t(round.titleKey);

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = finished ? this._t('debrief_intro') : this._t(round.briefingKey);

            for (var i = 0; i < this.ROUNDS.length; i++) {
                var panel = document.getElementById(this.ROUNDS[i].controlsId);
                if (panel) panel.style.display = (i === idx && !finished) ? 'block' : 'none';
            }

            var ds = state.domainState || {};
            if (ds.markets && ds.markets.length === 2) {
                var m1Label = document.getElementById('market1Label');
                var m2Label = document.getElementById('market2Label');
                if (m1Label) m1Label.textContent = this._t('entry_mode_market1') + ' (' + this._marketName(ds.markets[0]) + ')';
                if (m2Label) m2Label.textContent = this._t('entry_mode_market2') + ' (' + this._marketName(ds.markets[1]) + ')';
            }

            var debriefEl = document.getElementById('expansionDebrief');
            if (debriefEl) {
                var hist = (window.mySimulation && window.mySimulation.state && window.mySimulation.state.history) || [];
                if (finished && hist.length >= this.ROUNDS.length) {
                    debriefEl.innerHTML = this.formatCompletionMessage(this.getPerformanceSummary(hist));
                    debriefEl.style.display = 'block';
                } else {
                    debriefEl.innerHTML = '';
                    debriefEl.style.display = 'none';
                }
            }
        }

        validateDecisions(decisions) {
            var sim = window.mySimulation;
            var period = sim.state.currentPeriod || 1;
            var cash = sim.state.domainState.cash;
            var warn = function(key) { sim.uiManager.showNotification(sim.t(key), 'warning'); return false; };

            if (period === 1) {
                var mpSel = document.getElementById('marketPrioritySelect');
                if (mpSel) decisions.marketPriority = mpSel.value;
                var rbInput = document.getElementById('researchBudgetInput');
                if (rbInput) decisions.researchBudget = parseInt(rbInput.value, 10);
                if (!decisions.researchBudget || decisions.researchBudget < 50000 || decisions.researchBudget > 200000) return warn('research_warning');
            } else if (period === 2) {
                var em1 = document.getElementById('entryMode1Select');
                if (em1) decisions.entryMode1 = em1.value;
                var em2 = document.getElementById('entryMode2Select');
                if (em2) decisions.entryMode2 = em2.value;
                var a = EXP_MODEL.MODES[decisions.entryMode1];
                var b = EXP_MODEL.MODES[decisions.entryMode2];
                if (!a || !b) return warn('budget_exceeded_warning');
                var plan = sim.state.domainState.plan || {};
                var mk = EXP_MODEL.COMBOS[plan.marketPriority] || EXP_MODEL.COMBOS.usa_mexico;
                var cert = EXP_MODEL.MARKETS[mk[0]].extraCost + EXP_MODEL.MARKETS[mk[1]].extraCost;
                if (a.cost + b.cost + cert > cash) return warn('budget_exceeded_warning');
                if (a.cost + b.cost + cert + 240000 > cash) return warn('reserve_warning_r2');
            } else if (period === 3) {
                var rsSel = document.getElementById('responseStrategySelect');
                if (rsSel) decisions.responseStrategy = rsSel.value;
                var mbInput = document.getElementById('marketingBudgetInput');
                if (mbInput) decisions.marketingBudget = parseInt(mbInput.value, 10);
                if (!decisions.marketingBudget || decisions.marketingBudget < 200000 || decisions.marketingBudget > 800000) return warn('marketing_warning');
                var responseCost = decisions.responseStrategy === 'accelerate' ? 400000 : 0;
                if ((decisions.marketingBudget + responseCost) > cash) return warn('budget_exceeded_warning');
                if ((decisions.marketingBudget + responseCost + 40000) > cash) return warn('reserve_warning_r3');
            } else if (period === 4) {
                var locInput = document.getElementById('localizationInput');
                if (locInput) decisions.localizationLevel = parseInt(locInput.value, 10);
                var ppInput = document.getElementById('pricePointInput');
                if (ppInput) decisions.pricePoint = parseInt(ppInput.value, 10);
                if (!decisions.pricePoint || decisions.pricePoint < 12 || decisions.pricePoint > 28) return warn('price_warning');
                if (!decisions.localizationLevel || decisions.localizationLevel < 1 || decisions.localizationLevel > 5) return warn('price_warning');
                if (decisions.localizationLevel * 40000 > cash) return warn('budget_exceeded_warning');
            }
            return true;
        }

        calculateResults(state) {
            return this._computeRound(state);
        }

        /* Round model: every round re-values the whole plan with the board formula in EXP_MODEL.
           Decisions not yet taken are valued at the plan starting assumptions (EXP_MODEL.NEUTRAL). */
        _computeRound(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            ds.plan = ds.plan || {};
            var keys = { 1: ['marketPriority', 'researchBudget'], 2: ['entryMode1', 'entryMode2'], 3: ['responseStrategy', 'marketingBudget'], 4: ['localizationLevel', 'pricePoint'] }[period] || [];
            for (var i = 0; i < keys.length; i++) ds.plan[keys[i]] = d[keys[i]];
            if (period === 1) {
                ds.marketPriority = d.marketPriority;
                ds.markets = (EXP_MODEL.COMBOS[d.marketPriority] || EXP_MODEL.COMBOS.usa_mexico).slice();
            }

            var full = {};
            for (var k in EXP_MODEL.NEUTRAL) full[k] = EXP_MODEL.NEUTRAL[k];
            for (var p in ds.plan) full[p] = ds.plan[p];
            var proj = EXP_MODEL.project(full, period);
            var spentSoFar = EXP_MODEL.invested(full, period);
            var plannedTotal = EXP_MODEL.invested(full, 4);
            var investment = spentSoFar - ds.totalInvested;
            var prevScore = ds.strategicScore || 0;
            var prevRevenue = ds.projectedRevenueY3 || 0;
            var newScore = EXP_MODEL.score(proj.contribution, plannedTotal);

            ds.cash = EXP_MODEL.CAPITAL - spentSoFar;
            ds.totalInvested = spentSoFar;
            ds.projectedRevenueY3 = Math.round(proj.revenue);
            ds.projectedContribution = Math.round(proj.contribution);
            ds.projectedMargin = proj.margin;
            ds.flags = proj.flags;
            ds.strategicScore = newScore;

            var description = this._encodeDescription(period, d);
            ds.investmentHistory.push(investment);
            ds.revenueHistory.push(ds.projectedRevenueY3);
            ds.scoreHistory.push(newScore);
            ds.roundDescriptions.push(description);

            var tier = EXP_MODEL.tier(newScore);
            ds.score = newScore;
            ds.performanceTier = tier;
            ds.performance = { overallScore: newScore, grade: tier };

            var self = this;
            var nextPeriod = period + 1;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: nextPeriod, domainState: ds });
            }, 0);

            return {
                period: period,
                overallScore: newScore,
                score: newScore,
                totalScore: newScore,
                investment: investment,
                revenueImpact: ds.projectedRevenueY3 - prevRevenue,
                cumulativeRevenue: ds.projectedRevenueY3,
                scoreGain: newScore - prevScore,
                cash: ds.cash,
                description: description
            };
        }

        _encodeDescription(period, d) {
            if (period === 1) return 'p1|' + d.marketPriority + '|' + d.researchBudget;
            if (period === 2) return 'p2|' + d.entryMode1 + '|' + d.entryMode2;
            if (period === 3) return 'p3|' + d.responseStrategy + '|' + d.marketingBudget;
            return 'p4|' + d.localizationLevel + '|' + d.pricePoint;
        }

        _money(v) {
            var n = Math.round(Number(v) || 0);
            var s = Math.abs(n).toLocaleString('en-US');
            return (n < 0 ? '-$' : '$') + s;
        }

        _describe(code) {
            if (typeof code !== 'string' || code.indexOf('|') < 0) return String(code == null ? '' : code);
            var p = code.split('|');
            if (p[0] === 'p1') return this._t('opt_' + p[1]) + ' · ' + this._t('desc_research') + ' ' + this._money(p[2]);
            if (p[0] === 'p2') return this._t('mode_' + p[1]) + ' / ' + this._t('mode_' + p[2]);
            if (p[0] === 'p3') return this._t('resp_' + p[1]) + ' · ' + this._t('desc_marketing') + ' ' + this._money(p[2]);
            if (p[0] === 'p4') return this._t('desc_loc') + ' ' + p[1] + ' · ' + this._money(p[2]) + '/kg';
            return code;
        }

        setupUI(uiManager) {
            var self = this;
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashDisplay', 'domainState.cash', function(v) { return self._money(v); });
            uiManager.bind('investedDisplay', 'domainState.totalInvested', function(v) { return self._money(v); });
            uiManager.bind('revenueDisplay', 'domainState.projectedRevenueY3', function(v) { return self._money(v); });
            uiManager.bind('scoreDisplay', 'domainState.strategicScore');
        }

        getChartConfig() {
            return {
                performanceChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [
                            { label: 'Investment / Inversión ($)', data: [], backgroundColor: 'rgba(220,38,38,0.75)', borderColor: '#dc2626', borderWidth: 1, order: 2 },
                            { label: 'Projected revenue Y3 / Ingresos proyectados A3 ($)', data: [], type: 'line', borderColor: '#047857', backgroundColor: 'rgba(5,150,105,0.1)', borderWidth: 3, fill: true, tension: 0.2, pointRadius: 5, pointBackgroundColor: '#047857', order: 1 }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { labels: { font: { size: 11 }, color: '#475569' } }
                        },
                        scales: {
                            y: {
                                beginAtZero: true,
                                ticks: { callback: function(v) { return '$' + (v / 1000000).toFixed(1) + 'M'; }, color: '#475569', font: { size: 10 } },
                                grid: { color: '#f1f5f9' }
                            },
                            x: { ticks: { color: '#475569', font: { size: 10 } }, grid: { display: false } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var ds = (state && state.domainState) || {};
            var inv = ds.investmentHistory || [];
            var rev = ds.revenueHistory || [];
            var labels = inv.map(function(_, i) { return 'R' + (i + 1); });
            return { performanceChart: { labels: labels, datasets: [{ data: inv }, { data: rev }] } };
        }

        /* Mistakes and turning point, read from the run itself (the plan and the flags the model raised). */
        _diagnose(plan, flags) {
            var found = [];
            var markets = EXP_MODEL.COMBOS[plan.marketPriority] || [];
            if (markets.indexOf('europe') >= 0) found.push({ round: 1, key: 'tp_distance' });
            if (markets.indexOf('usa') < 0) found.push({ round: 1, key: 'tp_no_us' });
            if (plan.researchBudget > 150000) found.push({ round: 1, key: 'tp_research_limit' });
            if (flags.veryLateUS) found.push({ round: 2, key: 'tp_greenfield' });
            else if (flags.lateUS) found.push({ round: 2, key: 'tp_late_mode' });
            if (flags.rushQuality) found.push({ round: 3, key: 'tp_rush' });
            if (flags.rushMissed) found.push({ round: 3, key: 'tp_rush_missed' });
            if (plan.marketingBudget > 600000) found.push({ round: 3, key: 'tp_marketing_limit' });
            if (flags.twoStories) found.push({ round: 4, key: 'tp_two_stories' });
            return found;
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var last = history[history.length - 1];
            var ds = (last && last.domainState) || (window.mySimulation && window.mySimulation.state ? window.mySimulation.state.domainState : {}) || {};
            var plan = ds.plan || {};
            var flags = ds.flags || {};
            var res = last.results || {};
            var score = typeof res.overallScore === 'number' ? res.overallScore : (ds.strategicScore || 0);
            var totalInvested = history.reduce(function(s, r) { return s + (r.results ? r.results.investment : 0); }, 0);
            var revenue = res.cumulativeRevenue || ds.projectedRevenueY3 || 0;
            var contribution = ds.projectedContribution || 0;
            var tier = EXP_MODEL.tier(score);
            var mistakes = this._diagnose(plan, flags);

            var insights = [];
            insights.push({ key: 'ins_return', vals: [this._money(contribution), this._money(totalInvested), (totalInvested > 0 ? Math.round(contribution / totalInvested * 100) : 0) + '%'] });
            insights.push({ key: 'ins_capital', vals: [this._money(EXP_MODEL.CAPITAL - totalInvested)] });
            if (plan.responseStrategy) insights.push({ key: 'ins_resp_' + plan.responseStrategy, vals: [] });
            var mk = EXP_MODEL.COMBOS[plan.marketPriority] || [];
            if (mk[0] === 'usa' && plan.pricePoint > 24) insights.push({ key: 'ins_price_high', vals: [this._money(plan.pricePoint)] });
            else if (mk[0] === 'usa' && plan.pricePoint < 18) insights.push({ key: 'ins_price_low', vals: [this._money(plan.pricePoint)] });
            if (mk[1] === 'mexico' && plan.localizationLevel <= 2 && plan.pricePoint > 12) insights.push({ key: 'ins_mexico_ceiling', vals: [this._money(plan.pricePoint)] });
            else if (plan.localizationLevel >= 4) insights.push({ key: 'ins_loc_high', vals: [String(plan.localizationLevel)] });

            var weakest = 0;
            var worst = null;
            for (var i = 0; i < history.length; i++) {
                var g = history[i].results ? history[i].results.scoreGain : 0;
                if (i > 0 && (worst === null || g < worst)) { worst = g; weakest = i + 1; }
            }

            return {
                totalPeriods: history.length,
                totalInvested: totalInvested,
                overallScore: score,
                score: score,
                totalScore: score,
                composite: score,
                strategicScore: score,
                projectedRevenueY3: revenue,
                projectedContribution: contribution,
                capitalLeft: EXP_MODEL.CAPITAL - totalInvested,
                performance: tier,
                performanceKey: tier,
                performanceLabel: this._t('tier_' + tier),
                mistakes: mistakes.map(function(m) { return m.key; }),
                turningPoint: mistakes.length ? mistakes[0] : { round: weakest || 4, key: 'tp_none' },
                insights: insights.slice(0, 5)
            };
        }

        _fmt(text, vals) {
            var out = String(text);
            (vals || []).forEach(function(v, i) { out = out.split('{' + i + '}').join(v); });
            return out;
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var self = this;
            var score = typeof s.overallScore === 'number' ? s.overallScore : 0;
            var tier = s.performance || EXP_MODEL.tier(score);
            var tp = s.turningPoint || { round: 4, key: 'tp_none' };
            var h = '<div class="expansion-sim-cm" role="status" aria-live="polite">';
            h += '<h3 class="expansion-sim-cm-title">' + this._t('debrief_title') + '</h3>';
            h += '<p class="expansion-sim-cm-score"><strong>' + score + '/100</strong> · ' + this._t('tier_' + tier) + '</p>';
            h += '<ul class="expansion-sim-cm-kpis">';
            h += '<li>' + this._t('projected_revenue') + ': ' + this._money(s.projectedRevenueY3) + '</li>';
            h += '<li>' + this._t('kpi_contribution') + ': ' + this._money(s.projectedContribution) + '</li>';
            h += '<li>' + this._t('total_invested') + ': ' + this._money(s.totalInvested) + '</li>';
            h += '<li>' + this._t('col_remaining') + ': ' + this._money(s.capitalLeft) + '</li>';
            h += '</ul>';
            h += '<h4>' + this._t('dbf_turning') + ' (' + this._t('round_label') + ' ' + tp.round + ')</h4>';
            h += '<p>' + this._t(tp.key) + '</p>';
            var others = (s.mistakes || []).slice(1);
            if (others.length) {
                h += '<h4>' + this._t('dbf_also') + '</h4><ul>';
                others.forEach(function(k) { h += '<li>' + self._t(k) + '</li>'; });
                h += '</ul>';
            }
            h += '<h4>' + this._t('dbf_insights') + '</h4><ul>';
            (s.insights || []).forEach(function(it) { h += '<li>' + self._fmt(self._t(it.key), it.vals) + '</li>'; });
            h += '</ul>';
            h += '<h4>' + this._t('dbf_questions') + '</h4><ol>';
            h += '<li>' + this._t('dq_1') + '</li><li>' + this._t('dq_2') + '</li><li>' + this._t('dq_3') + '</li>';
            h += '</ol></div>';
            return h;
        }

        getHint(state, results) {
            if (state.currentPeriod === 2 && state.domainState.cash < 500000) return window.mySimulation.t('hint_budget_tight');
            return null;
        }

        getHistoryTableConfig() {
            var self = this;
            return [
                { key: 'results.description', label: 'Decision', i18nKey: 'col_decision', formatter: function(v) { return self._describe(v); } },
                { key: 'results.investment', label: 'Investment', i18nKey: 'col_investment', formatter: function(v) { return self._money(v); } },
                { key: 'results.revenueImpact', label: 'Revenue Impact', i18nKey: 'col_revenue_impact', formatter: function(v) { return self._money(v); } },
                { key: 'results.scoreGain', label: 'Score +', i18nKey: 'col_score_gain' },
                { key: 'results.cash', label: 'Remaining Capital', i18nKey: 'col_remaining', formatter: function(v) { return self._money(v); } }
            ];
        }

        getPresets() { return null; }


        getTranslations() {
            return {
